window.QBANK["m1w1"] = [
  {"level": 1, "q": "Dòng model Claude nào nhanh và rẻ nhất, phù hợp cho phân loại hoặc trích xuất khối lượng lớn?", "options": ["Haiku", "Opus", "Sonnet", "Claude Code"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Haiku là dòng nhỏ nhất, độ trễ thấp và giá thấp nhất, hợp với việc đơn giản lặp lại nhiều lần. <br><strong>Vì sao các lựa chọn khác sai:</strong> Opus mạnh nhất nhưng đắt nhất; Sonnet là mức cân bằng ở giữa; Claude Code là công cụ agent lập trình, không phải một dòng model."},
  {"level": 1, "q": "Dòng model nào được mô tả là \"cân bằng chất lượng – tốc độ – giá\", phù hợp phần lớn ứng dụng sản phẩm như chatbot hay xử lý tài liệu?", "options": ["Opus", "Haiku", "Claude Instant", "Sonnet"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Sonnet đứng giữa Opus và Haiku, là lựa chọn mặc định hợp lý cho nhiều sản phẩm. <br><strong>Vì sao các lựa chọn khác sai:</strong> Opus dành cho việc suy luận sâu, đắt hơn; Haiku ưu tiên tốc độ và giá; \"Claude Instant\" không phải dòng model trong bài học."},
  {"level": 1, "q": "Mọi tương tác với Claude API (gửi prompt, nhận câu trả lời) đi qua endpoint nào?", "options": ["<code>POST /v1/chat/completions</code>", "<code>GET /v1/conversations</code>", "<code>POST /v1/messages</code>", "<code>POST /v1/sessions/{id}/reply</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Messages API là endpoint duy nhất để tạo câu trả lời: <code>POST /v1/messages</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>/v1/chat/completions</code> là tên endpoint của nhà cung cấp khác; Claude API không có endpoint conversation hay session lưu hội thoại vì API là stateless."},
  {"level": 1, "q": "Tham số <code>max_tokens</code> trong request giới hạn điều gì?", "options": ["Tổng số token của cả context window", "Số token output tối đa của một lần trả lời", "Số token input tối đa được gửi lên", "Số lượt user/assistant trong messages"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> <code>max_tokens</code> chỉ chặn độ dài phần model sinh ra trong một lần trả lời. <br><strong>Vì sao các lựa chọn khác sai:</strong> Context window là giới hạn của model, không phải tham số này; input không bị <code>max_tokens</code> giới hạn; số lượt hội thoại không liên quan tới tham số này."},
  {"level": 1, "q": "Response dừng giữa câu vì chạm giới hạn output. Trường <code>stop_reason</code> sẽ có giá trị nào?", "options": ["<code>\"end_turn\"</code>", "<code>\"max_tokens\"</code>", "<code>\"length\"</code>", "<code>\"truncated\"</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Khi model chạm giới hạn <code>max_tokens</code> trước khi viết xong, API trả <code>stop_reason = \"max_tokens\"</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>\"end_turn\"</code> là khi model tự kết thúc; <code>\"length\"</code> và <code>\"truncated\"</code> không phải giá trị của Claude API."},
  {"level": 1, "q": "Khi Claude tự hoàn thành câu trả lời một cách tự nhiên, <code>stop_reason</code> là gì?", "options": ["<code>\"max_tokens\"</code>", "<code>\"stop\"</code>", "<code>\"end_turn\"</code>", "<code>\"complete\"</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> <code>\"end_turn\"</code> nghĩa là model đã kết thúc lượt trả lời mà không bị cắt. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>\"max_tokens\"</code> là bị cắt vì giới hạn; <code>\"stop\"</code> và <code>\"complete\"</code> không phải giá trị hợp lệ của Messages API."},
  {"level": 1, "q": "Context window của một request bao gồm những gì?", "options": ["System prompt + lịch sử hội thoại + tài liệu + định nghĩa tool + output", "Chỉ câu hỏi mới nhất của người dùng", "Chỉ system prompt và output", "Toàn bộ các request trước đó mà server đã lưu"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Context window là tổng số token model nhìn thấy trong một request, gồm mọi thứ bạn gửi lên và cả phần output. <br><strong>Vì sao các lựa chọn khác sai:</strong> Câu hỏi mới nhất chỉ là một phần; bỏ lịch sử, tài liệu, tool là thiếu; server không lưu request trước vì API stateless."},
  {"level": 1, "q": "Token là gì trong ngữ cảnh model ngôn ngữ?", "options": ["Đúng một từ hoàn chỉnh", "Một ký tự Unicode", "Một câu hoàn chỉnh", "Đơn vị model đọc và viết, thường là một phần của từ"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Tokenizer tách văn bản thành các mảnh nhỏ (thường là một phần của từ); chi phí và giới hạn đều tính theo token. <br><strong>Vì sao các lựa chọn khác sai:</strong> Token không trùng khớp một-một với từ, ký tự hay câu; một từ có thể là nhiều token và một token có thể chứa vài ký tự."},
  {"level": 1, "q": "Trong <code>apps/api</code>, đoạn khởi tạo sau đọc API key từ đâu?<pre><code>import Anthropic from \"@anthropic-ai/sdk\";\n\nconst client = new Anthropic();</code></pre>", "options": ["Biến môi trường <code>ANTHROPIC_API_KEY</code> (hoặc thông tin xác thực khác trong môi trường)", "File <code>.mcp.json</code> ở gốc repo", "File <code>package.json</code> của <code>apps/api</code>", "Cookie của trình duyệt người dùng"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Khởi tạo không tham số, SDK tự tìm credential trong môi trường, mặc định là <code>ANTHROPIC_API_KEY</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>.mcp.json</code> dùng cấu hình MCP server cho Claude Code; <code>package.json</code> không chứa secret; code chạy ở backend không đọc cookie trình duyệt để lấy key."},
  {"level": 1, "q": "Dòng import nào đúng để dùng Claude API SDK trong NestJS (TypeScript)?", "options": ["<code>import { Claude } from \"anthropic\";</code>", "<code>import Anthropic from \"@anthropic/claude\";</code>", "<code>import Anthropic from \"@anthropic-ai/sdk\";</code>", "<code>const Anthropic = require(\"claude-sdk\");</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> SDK TypeScript chính thức có tên package <code>@anthropic-ai/sdk</code> và export default là class <code>Anthropic</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>anthropic</code> là tên package Python; <code>@anthropic/claude</code> và <code>claude-sdk</code> không phải package SDK chính thức."},
  {"level": 1, "q": "Trường nào của response cho biết số token input và output thực tế đã dùng?", "options": ["<code>stop_reason</code>", "<code>content</code>", "<code>model</code>", "<code>usage</code> (gồm <code>input_tokens</code>, <code>output_tokens</code>)"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> <code>usage</code> chứa <code>input_tokens</code>, <code>output_tokens</code> và các trường cache, là cơ sở để tính chi phí thật. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>stop_reason</code> cho biết lý do dừng; <code>content</code> là nội dung trả về; <code>model</code> chỉ là tên model đã dùng."},
  {"level": 1, "q": "Chuỗi model ID nào được viết đúng theo bài học?", "options": ["<code>claude-opus-5-20260101</code>", "<code>claude-opus-5</code>", "<code>opus-5</code>", "<code>claude-5-opus</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Model ID là chuỗi chính xác lấy từ trang Models hoặc <code>client.models.list()</code>, ví dụ <code>claude-opus-5</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> Tự thêm ngày tháng vào đuôi là bẫy thường gặp; bỏ tiền tố <code>claude-</code> hoặc đảo thứ tự đều tạo ID không tồn tại."},
  {"level": 1, "q": "Trong TypeScript SDK, cách nào đếm chính xác số token input của một prompt trước khi gửi?", "options": ["<code>client.messages.countTokens({ model, system, messages })</code>", "Đếm số từ rồi nhân 1,3", "Gửi request với <code>max_tokens: 0</code> rồi đọc lỗi", "<code>client.tokens.estimate(text)</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Endpoint đếm token trả về <code>input_tokens</code> theo đúng tokenizer của model, không sinh output. <br><strong>Vì sao các lựa chọn khác sai:</strong> Ước lượng theo số từ sai lệch, nhất là tiếng Việt; cố tình gây lỗi không phải cách đo; <code>client.tokens.estimate</code> không tồn tại trong SDK."},
  {"level": 1, "q": "Batch API (xử lý bất đồng bộ theo lô) giúp giảm chi phí khoảng bao nhiêu so với gọi thường?", "options": ["Khoảng 5%", "Khoảng 90%", "Khoảng 50%", "Không giảm, chỉ tăng tốc độ"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Bài học nêu Batch API rẻ hơn khoảng 50%, đổi lại kết quả không trả về ngay. <br><strong>Vì sao các lựa chọn khác sai:</strong> 5% là quá thấp; mức giảm khoảng 90% là của phần đọc từ prompt cache, không phải Batch; Batch không nhằm tăng tốc mà nhằm giảm giá cho việc không cần kết quả ngay."},
  {"level": 1, "q": "So với tiếng Anh, văn bản tiếng Việt có dấu cho cùng một lượng ý thường thế nào về số token?", "options": ["Luôn tốn đúng bằng", "Luôn tốn ít hơn một nửa", "Không được tính token", "Thường tốn nhiều token hơn"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Tokenizer tối ưu tốt cho tiếng Anh; tiếng Việt có dấu thường bị tách thành nhiều mảnh hơn nên tốn nhiều token hơn. <br><strong>Vì sao các lựa chọn khác sai:</strong> Số token không bằng nhau giữa các ngôn ngữ; tiếng Việt không rẻ hơn; mọi văn bản gửi lên đều được tính token."},
  {"level": 1, "q": "Bề mặt nào của Claude là agent lập trình chạy trong terminal, IDE, desktop và web?", "options": ["claude.ai Projects", "Claude Code", "Amazon Bedrock", "Batch API"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Claude Code là agent đọc/sửa code, chạy lệnh, dùng trong terminal và IDE. <br><strong>Vì sao các lựa chọn khác sai:</strong> claude.ai Projects là giao diện chat cho người dùng cuối; Bedrock là nền tảng cloud để gọi model; Batch API là chế độ gọi API theo lô."},
  {"level": 1, "q": "Công ty chạy toàn bộ hạ tầng trên AWS muốn gọi Claude qua dịch vụ của AWS. Dịch vụ nào phù hợp?", "options": ["Amazon Lex", "AWS Amplify", "Amazon Bedrock", "Amazon Comprehend"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Claude có sẵn trên Amazon Bedrock, một trong các nền tảng cloud được bài học liệt kê. <br><strong>Vì sao các lựa chọn khác sai:</strong> Lex là dịch vụ xây chatbot của AWS; Amplify là dịch vụ hosting/frontend; Comprehend là dịch vụ NLP riêng của AWS, không phải nơi gọi Claude."},
  {"level": 1, "q": "Trong mảng <code>messages</code>, các lượt hội thoại dùng những <code>role</code> nào là chính?", "options": ["<code>human</code> và <code>ai</code>", "<code>client</code> và <code>server</code>", "<code>input</code> và <code>output</code>", "<code>user</code> và <code>assistant</code> xen kẽ"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Messages API nhận danh sách lượt <code>user</code> / <code>assistant</code>; vai trò và quy tắc chung đặt ở tham số <code>system</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>human</code>/<code>ai</code>, <code>client</code>/<code>server</code>, <code>input</code>/<code>output</code> không phải giá trị role của Messages API."},
  {"level": 1, "q": "Phần tử đầu tiên của mảng <code>messages</code> phải có role gì?<pre><code>await client.messages.create({\n  model: \"claude-opus-5\",\n  max_tokens: 1024,\n  messages: [\n    { role: ???, content: \"Xin chào, tôi cần tư vấn gói cước.\" },\n  ],\n});</code></pre>", "options": ["<code>assistant</code>", "<code>user</code>", "<code>system</code>", "Tuỳ ý, không có quy định"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Hội thoại phải bắt đầu bằng lượt <code>user</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> Bắt đầu bằng <code>assistant</code> không hợp lệ; chỉ dẫn hệ thống đặt ở tham số <code>system</code> top-level chứ không phải <code>messages[0]</code>; thứ tự có quy định rõ."},
  {"level": 1, "q": "Trong Messages API, chỉ dẫn vai trò và quy tắc chung cho cả hội thoại nên đặt ở đâu?", "options": ["Tham số top-level <code>system</code>", "Phần tử <code>messages[0]</code> với <code>role: \"system\"</code>", "Header HTTP <code>X-System-Prompt</code>", "Trường <code>metadata</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Tham số <code>system</code> là nơi dành cho vai trò, phạm vi và quy tắc ổn định. <br><strong>Vì sao các lựa chọn khác sai:</strong> Đặt message role system ở vị trí đầu mảng không hợp lệ; không có header <code>X-System-Prompt</code>; <code>metadata</code> không dùng để chỉ dẫn model."},
  {"level": 1, "q": "Vì sao code TypeScript cần kiểm tra <code>block.type === \"text\"</code> trước khi đọc <code>block.text</code>?<pre><code>for (const block of response.content) {\n  if (block.type === \"text\") {\n    console.log(block.text);\n  }\n}</code></pre>", "options": ["Vì <code>content</code> luôn là một chuỗi string", "Vì SDK chỉ trả text khi <code>stop_reason</code> là <code>\"max_tokens\"</code>", "<code>response.content</code> là mảng content block có nhiều loại (text, thinking, tool_use...), cần thu hẹp kiểu trước khi đọc", "Vì kiểm tra này giúp giảm chi phí token"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> <code>content</code> là một union có nhiều loại block; TypeScript báo lỗi nếu đọc <code>.text</code> khi chưa thu hẹp kiểu. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>content</code> không phải string; text có mặt bất kể stop_reason; kiểm tra kiểu không ảnh hưởng chi phí."},
  {"level": 1, "q": "Công thức tính chi phí của một request là gì (giá niêm yết theo USD / 1 triệu token)?", "options": ["(input_tokens + output_tokens) × giá input", "output_tokens × giá output (input miễn phí)", "Số request × giá cố định mỗi request", "(input_tokens × giá input + output_tokens × giá output) / 1.000.000"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Input và output có đơn giá khác nhau, nên phải nhân riêng rồi cộng lại và chia cho 1 triệu. <br><strong>Vì sao các lựa chọn khác sai:</strong> Dùng chung giá input bỏ qua việc output đắt hơn; input không miễn phí; Claude API không tính giá cố định theo request."},
  {"level": 1, "q": "So sánh đơn giá token output và token input, nhận định nào đúng?", "options": ["Output thường đắt hơn input nhiều lần (khoảng 5 lần)", "Output và input luôn bằng giá", "Input đắt hơn output", "Output miễn phí nếu dùng streaming"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Bài học nêu output thường đắt gấp khoảng 5 lần input, nên output dài ảnh hưởng mạnh tới chi phí. <br><strong>Vì sao các lựa chọn khác sai:</strong> Hai loại token có giá khác nhau; input rẻ hơn chứ không đắt hơn; streaming không làm output miễn phí."},
  {"level": 1, "q": "Việc nào phù hợp nhất với dòng Opus?", "options": ["Phân loại 2 triệu email mỗi ngày thành 8 nhóm", "Agent sửa bug trong repo lớn, chạy test và mở pull request", "Trích xuất số điện thoại từ form đăng ký", "Subagent chỉ đọc file và tóm tắt"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Việc nhiều bước, suy luận khó và sai thì tốn kém là thế mạnh của Opus. <br><strong>Vì sao các lựa chọn khác sai:</strong> Phân loại hàng loạt, trích xuất đơn giản và subagent đọc/tóm tắt là việc nhẹ, nên dùng Haiku hoặc Sonnet để tiết kiệm."},
  {"level": 1, "q": "Tên package npm của Claude API SDK cần thêm vào <code>apps/api</code> là gì?", "options": ["<code>anthropic</code>", "<code>@anthropic/claude-api</code>", "<code>claude-js</code>", "<code>@anthropic-ai/sdk</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> SDK TypeScript chính thức là <code>@anthropic-ai/sdk</code>, ví dụ <code>pnpm --filter api add @anthropic-ai/sdk</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>anthropic</code> là SDK Python cài bằng pip; hai tên còn lại không phải package chính thức."},
  {"level": 1, "q": "Nói Messages API là \"stateless\" nghĩa là gì?", "options": ["Server lưu hội thoại theo API key trong 24 giờ", "Server không lưu hội thoại giữa hai request; client phải gửi lại lịch sử mỗi lượt", "API không trả về <code>usage</code>", "API chỉ nhận một message mỗi request"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Mỗi request độc lập; muốn hội thoại nhiều lượt, ứng dụng tự lưu và gửi lại toàn bộ lịch sử. <br><strong>Vì sao các lựa chọn khác sai:</strong> Không có cơ chế lưu hội thoại theo key; <code>usage</code> luôn có trong response; <code>messages</code> là mảng nhiều lượt."},
  {"level": 1, "q": "Với <code>claude-opus-5</code>, cấu hình thinking được khuyến nghị là gì?", "options": ["<code>thinking: { type: \"adaptive\" }</code>", "<code>thinking: { type: \"enabled\", budget_tokens: 8000 }</code>", "<code>thinking: true</code>", "<code>reasoning: \"deep\"</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Opus 5 dùng adaptive thinking (và thinking bật mặc định); <code>budget_tokens</code> đã bị bỏ trên model này. <br><strong>Vì sao các lựa chọn khác sai:</strong> Gửi <code>budget_tokens</code> cho Opus 5 trả lỗi 400; <code>thinking: true</code> và <code>reasoning</code> không phải cú pháp của Messages API."},
  {"level": 1, "q": "Muốn điều chỉnh mức độ \"cố gắng\" (effort) của model trong request, bạn đặt tham số ở đâu?", "options": ["<code>effort</code> bên trong từng message", "<code>max_tokens: \"medium\"</code>", "<code>output_config: { effort: \"medium\" }</code>", "Header HTTP <code>X-Effort</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Effort được đặt trong <code>output_config</code> với các mức low | medium | high | xhigh | max. <br><strong>Vì sao các lựa chọn khác sai:</strong> Effort không nằm trong message; <code>max_tokens</code> là số nguyên giới hạn output; không có header <code>X-Effort</code>."},
  {"level": 1, "q": "Để gọi Claude trên Amazon Bedrock bằng TypeScript theo bài học, bạn dùng client nào?", "options": ["<code>new Anthropic({ provider: \"bedrock\" })</code> từ <code>@anthropic-ai/sdk</code>", "<code>BedrockClaudeClient</code> từ <code>aws-sdk</code>", "<code>ClaudeClient</code> từ <code>@aws/claude</code>", "<code>AnthropicBedrockMantle</code> từ <code>@anthropic-ai/bedrock-sdk</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Package <code>@anthropic-ai/bedrock-sdk</code> cung cấp <code>AnthropicBedrockMantle</code>, khởi tạo với <code>awsRegion</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> Client <code>Anthropic</code> gốc không có tuỳ chọn <code>provider</code>; hai tên còn lại không tồn tại."},
  {"level": 1, "q": "Model ID khi gọi Claude Opus 5 qua Bedrock (client <code>AnthropicBedrockMantle</code>) có dạng nào?", "options": ["<code>claude-opus-5</code>", "<code>anthropic.claude-opus-5</code>", "<code>bedrock/claude-opus-5</code>", "<code>aws.claude.opus5</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Trên Bedrock, model ID có tiền tố <code>anthropic.</code>, ví dụ <code>anthropic.claude-opus-5</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>claude-opus-5</code> là ID của Claude API trực tiếp; hai dạng còn lại không đúng quy ước ID của Bedrock."},
  {"level": 2, "q": "Chatbot trong NestJS \"quên\" mức lương khách vừa nói ở lượt trước. Nguyên nhân trong đoạn code sau là gì?<pre><code>@Injectable()\nexport class ChatService {\n  constructor(private readonly claude: Anthropic) {}\n\n  async ask(question: string) {\n    const r = await this.claude.messages.create({\n      model: \"claude-opus-5\",\n      max_tokens: 2048,\n      system: SYSTEM,\n      messages: [{ role: \"user\", content: question }],\n    });\n    return r;\n  }\n}</code></pre>", "options": ["Chỉ gửi câu hỏi mới nhất; vì API stateless nên phải gửi lại toàn bộ lịch sử hội thoại", "<code>max_tokens</code> quá thấp nên model không nhớ", "Thiếu <code>thinking: { type: \"adaptive\" }</code>", "Phải bật prompt caching để model nhớ"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Server không giữ trạng thái, nên model chỉ thấy đúng những gì có trong <code>messages</code> của request hiện tại. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>max_tokens</code> giới hạn output, không liên quan trí nhớ; thinking không lấy lại được lịch sử không được gửi; caching chỉ giảm chi phí phần tiền tố lặp lại, bạn vẫn phải gửi nội dung."},
  {"level": 2, "q": "Endpoint <code>/articles/generate</code> trả về bài viết bị cắt giữa chừng. Log cho thấy như sau. Cách sửa đúng nhất?<pre><code>{\"stop_reason\":\"max_tokens\",\"usage\":{\"input_tokens\":812,\"output_tokens\":300}}</code></pre>", "options": ["Đổi sang Haiku để viết nhanh hơn", "Bật prompt caching cho system prompt", "Tăng <code>max_tokens</code> cho đủ độ dài bài viết (và dùng streaming nếu output dài)", "Rút ngắn system prompt để còn chỗ cho output"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> <code>stop_reason = \"max_tokens\"</code> với output đúng bằng 300 token cho thấy giới hạn output đặt quá thấp. <br><strong>Vì sao các lựa chọn khác sai:</strong> Đổi model không đổi giới hạn bạn đặt; caching chỉ ảnh hưởng chi phí input; system prompt ngắn đi không nâng giới hạn output."},
  {"level": 2, "q": "Chatbot nhận 10.000 request/ngày, mỗi request 1.500 token input và 400 token output. Giá: 5 USD/1M input, 25 USD/1M output. Chi phí mỗi ngày là bao nhiêu?", "options": ["17,5 USD", "175 USD", "1.750 USD", "75 USD"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Mỗi request: (1.500 × 5 + 400 × 25) / 1.000.000 = 0,0175 USD; nhân 10.000 request = 175 USD. <br><strong>Vì sao các lựa chọn khác sai:</strong> 17,5 và 1.750 là sai 10 lần do nhầm đơn vị; 75 USD chỉ tính phần input, bỏ quên phần output đắt hơn."},
  {"level": 2, "q": "Job phân loại chạy 20.000 request/ngày, mỗi request 2.000 token input và 500 token output, giá 1 USD/1M input và 5 USD/1M output. Chi phí mỗi ngày?", "options": ["45 USD", "900 USD", "90 USD", "40 USD"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Mỗi request: (2.000 × 1 + 500 × 5) / 1.000.000 = 0,0045 USD; × 20.000 = 90 USD. <br><strong>Vì sao các lựa chọn khác sai:</strong> 45 USD là tính sai một nửa số request; 900 USD sai 10 lần; 40 USD chỉ tính input."},
  {"level": 2, "q": "CloudWatch log của một phiên chat cho thấy <code>input_tokens</code> tăng dần: 1.200 → 2.400 → 3.700 → 5.100 dù câu hỏi mỗi lượt đều ngắn. Giải thích nào đúng?<pre><code>{\"conversationId\":\"c_91\",\"turn\":1,\"input_tokens\":1200,\"output_tokens\":310}\n{\"conversationId\":\"c_91\",\"turn\":2,\"input_tokens\":2400,\"output_tokens\":280}\n{\"conversationId\":\"c_91\",\"turn\":3,\"input_tokens\":3700,\"output_tokens\":350}\n{\"conversationId\":\"c_91\",\"turn\":4,\"input_tokens\":5100,\"output_tokens\":300}</code></pre>", "options": ["Mỗi lượt gửi lại toàn bộ lịch sử, nên input tăng theo số lượt", "Model tự lưu hội thoại và tính phí lưu trữ", "Tokenizer thay đổi theo thời gian", "Streaming làm tăng input"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Vì API stateless, lịch sử được gửi lại mỗi lần; lượt sau luôn tốn nhiều input hơn lượt trước. <br><strong>Vì sao các lựa chọn khác sai:</strong> Server không lưu hội thoại; tokenizer của một model không thay đổi giữa các request; streaming chỉ ảnh hưởng cách nhận output."},
  {"level": 2, "q": "Đoạn code TypeScript sau báo lỗi biên dịch <code>Property 'text' does not exist on type 'ContentBlock'</code>. Cách sửa đúng?<pre><code>const r = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 1024, messages });\nreturn r.content[0].text;</code></pre>", "options": ["Ép kiểu <code>response.content as string</code>", "Đổi sang <code>response.text</code>", "Tắt <code>strict</code> trong <code>tsconfig.json</code>", "Duyệt <code>response.content</code> và chỉ đọc <code>.text</code> khi <code>block.type === \"text\"</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> <code>content</code> là union của nhiều loại block; thu hẹp theo <code>type</code> là cách an toàn và đúng kiểu. <br><strong>Vì sao các lựa chọn khác sai:</strong> Ép kiểu sang string sai về dữ liệu thật; <code>response.text</code> không tồn tại; tắt strict chỉ che lỗi và có thể đọc nhầm block không phải text."},
  {"level": 2, "q": "Review PR thấy đoạn code sau trong <code>apps/api/src/claude/claude.service.ts</code>. Vấn đề chính và cách sửa?<pre><code>const client = new Anthropic({ apiKey: \"sk-ant-api03-xxxxxxxx\" });</code></pre>", "options": ["API key bị ghi cứng và sẽ lên git; phải đọc từ biến môi trường, trên production lấy từ AWS Secrets Manager", "Không có vấn đề vì repo private", "Chỉ cần đổi tên biến thành <code>KEY</code>", "Chuyển key sang <code>apps/web/.env.local</code> với tiền tố <code>NEXT_PUBLIC_</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Key trong code sẽ nằm trong lịch sử git; key phải được nạp từ môi trường, trên ECS lấy từ Secrets Manager. <br><strong>Vì sao các lựa chọn khác sai:</strong> Repo private vẫn có thể lộ và nhiều người đọc được; đổi tên biến không thay đổi gì; tiền tố <code>NEXT_PUBLIC_</code> còn đưa key ra trình duyệt."},
  {"level": 2, "q": "Một dev đặt <code>max_tokens: 200</code> cho mọi request \"để tiết kiệm tiền\". Nhận định nào đúng?", "options": ["Đúng, <code>max_tokens</code> càng thấp chi phí input càng thấp", "Đúng, API tính phí theo <code>max_tokens</code> chứ không theo output thật", "Không tiết kiệm được: bạn chỉ trả tiền cho token thật sự sinh ra, giới hạn thấp chỉ làm output bị cắt", "Đúng, vì model sẽ tự viết ngắn gọn hơn mà không bị cắt"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Phí output tính theo <code>output_tokens</code> thực tế; <code>max_tokens</code> thấp chỉ chặn ở giữa chừng. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>max_tokens</code> không ảnh hưởng input; API không tính phí theo giới hạn đặt ra; model không biết trước để tự rút gọn nên thường bị cắt giữa câu."},
  {"level": 2, "q": "Shop mỹ phẩm phân loại 50.000 đánh giá/ngày (khen, chê giao hàng, chê sản phẩm...). Lựa chọn nào hợp lý nhất để giảm chi phí mà vẫn an toàn về chất lượng?", "options": ["Dùng Opus với effort max cho chắc chắn", "Chạy eval trên vài trăm đánh giá có nhãn tay, nếu Haiku đạt ngưỡng thì chuyển phân loại sang Haiku", "Chuyển thẳng sang Haiku không cần đo", "Giảm <code>max_tokens</code> xuống 5 cho mọi request"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Phân loại là việc đơn giản khối lượng lớn; đổi model rẻ phải dựa trên số đo từ eval. <br><strong>Vì sao các lựa chọn khác sai:</strong> Opus effort max quá đắt cho phân loại; đổi model không đo có thể làm giảm chất lượng mà không biết; <code>max_tokens</code> quá nhỏ dễ cắt cả nhãn."},
  {"level": 2, "q": "Chatbot tư vấn sản phẩm trên Next.js cần phản hồi nhanh (người dùng thấy chữ trong 2–3 giây), độ khó trung bình. Cấu hình khởi đầu hợp lý?", "options": ["Opus với effort max, không streaming", "Batch API để gom request", "Haiku kèm <code>max_tokens: 50</code>", "Sonnet kèm streaming, sau đó thử Haiku nếu eval cho thấy đủ tốt"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Sonnet cân bằng chất lượng và tốc độ; streaming giúp người dùng thấy chữ sớm. <br><strong>Vì sao các lựa chọn khác sai:</strong> Opus effort max tăng độ trễ và chi phí; Batch API không trả kết quả ngay; <code>max_tokens</code> 50 cắt cụt câu trả lời."},
  {"level": 2, "q": "Route handler Next.js sau sinh báo cáo dài (hàng chục nghìn token) và hay bị timeout HTTP. Cách sửa phù hợp nhất?<pre><code>// apps/web/app/api/report/route.ts\nexport async function POST(req: Request) {\n  const { topic } = await req.json();\n  const r = await client.messages.create({\n    model: \"claude-opus-5\",\n    max_tokens: 32000,\n    messages: [{ role: \"user\", content: `Viết báo cáo chi tiết về ${topic}` }],\n  });\n  return Response.json(r.content);\n}</code></pre>", "options": ["Giảm <code>max_tokens</code> xuống 1.000", "Đổi sang Batch API để có kết quả ngay", "Chuyển sang <code>client.messages.stream(...)</code> và đẩy dần text về client", "Bật prompt caching"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Với output dài, streaming giữ kết nối có dữ liệu liên tục và giảm rủi ro timeout. <br><strong>Vì sao các lựa chọn khác sai:</strong> Giảm <code>max_tokens</code> làm báo cáo bị cắt; Batch API là bất đồng bộ, không trả ngay; caching không giải quyết thời gian sinh output."},
  {"level": 2, "q": "Bảng Prisma sau dùng để theo dõi chi phí Claude theo tính năng. Thiếu trường quan trọng nào để tính chi phí đúng?<pre><code>model UsageLog {\n  id          String   @id @default(cuid())\n  feature     String\n  model       String\n  inputTokens Int\n  createdAt   DateTime @default(now())\n}</code></pre>", "options": ["<code>userAgent</code>", "<code>stopReason</code> là đủ để suy ra chi phí", "<code>updatedAt</code>", "<code>outputTokens</code> – vì output có đơn giá riêng và thường đắt hơn input"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Chi phí = input × giá input + output × giá output; không có số token output thì không tính được. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>userAgent</code> và <code>updatedAt</code> không ảnh hưởng chi phí; <code>stopReason</code> cho biết lý do dừng, không cho biết số token."},
  {"level": 2, "q": "Trước khi gửi hợp đồng dài vào NestJS service, bạn muốn biết nó tốn bao nhiêu token input. Đoạn nào đúng?", "options": ["<code>const c = await client.messages.countTokens({ model: \"claude-opus-5\", system, messages }); console.log(c.input_tokens);</code>", "<code>const c = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 0, messages });</code>", "<code>const c = text.split(\" \").length * 1.3;</code>", "<code>const c = await client.models.count(text);</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> <code>countTokens</code> nhận cùng cấu trúc với request và trả <code>input_tokens</code> chính xác. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>max_tokens: 0</code> không phải cách đếm và không hợp lệ; nhân hệ số theo số từ chỉ là ước lượng; <code>models.count</code> không tồn tại."},
  {"level": 2, "q": "Người dùng dán cả bộ log 2 MB vào chat, request trả về lỗi 400. Nguyên nhân khả dĩ nhất và hướng xử lý?", "options": ["Hết hạn mức tài khoản, cần nạp tiền", "Input vượt context window; cần đếm token trước và cắt/tóm tắt hoặc chia nhỏ dữ liệu", "<code>max_tokens</code> quá thấp, cần tăng lên", "Model đang quá tải, chỉ cần thử lại"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Theo luồng request, vượt context window dẫn tới lỗi 400; phải giảm lượng input. <br><strong>Vì sao các lựa chọn khác sai:</strong> Hết hạn mức hay quá tải có mã lỗi khác và không gắn với dữ liệu quá lớn; tăng <code>max_tokens</code> còn làm tổng nhu cầu context lớn hơn."},
  {"level": 2, "q": "Để hội thoại nhiều lượt đúng, sau mỗi lượt bạn cập nhật <code>history</code> thế nào?<pre><code>history.push({ role: \"user\", content: question });\nconst r = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 2048, system: SYSTEM, messages: history });\n// dòng tiếp theo?</code></pre>", "options": ["Thêm câu hỏi của user trước khi gọi, sau đó thêm <code>{ role: \"assistant\", content: r.content }</code> vào history", "Chỉ thêm câu hỏi mới, bỏ câu trả lời", "Ghi đè history bằng câu hỏi mới nhất", "Lưu câu trả lời vào system prompt"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Lịch sử phải có cả lượt user và assistant xen kẽ để model thấy đầy đủ hội thoại. <br><strong>Vì sao các lựa chọn khác sai:</strong> Bỏ câu trả lời làm mất ngữ cảnh; ghi đè history làm \"quên\" hội thoại; nhồi câu trả lời vào system làm lẫn quy tắc với dữ liệu và phá cache."},
  {"level": 2, "q": "Tham số nào là tuỳ chọn trong một request Messages API tối thiểu?", "options": ["<code>model</code>", "<code>max_tokens</code>", "<code>messages</code>", "<code>system</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> <code>system</code> có thể bỏ qua; ba tham số còn lại là bắt buộc cho một request cơ bản. <br><strong>Vì sao các lựa chọn khác sai:</strong> Thiếu <code>model</code>, <code>max_tokens</code> hoặc <code>messages</code> thì request không hợp lệ."},
  {"level": 2, "q": "File <code>.env</code> của <code>apps/api</code> có dòng sau và mọi request đều lỗi \"model not found\". Cách sửa?<pre><code>CLAUDE_MODEL=claude-opus-5-20260615</code></pre>", "options": ["Giữ nguyên và thêm header phiên bản API mới", "Dùng đúng chuỗi ID như <code>claude-opus-5</code>, lấy từ trang Models hoặc <code>client.models.list()</code>", "Đổi sang <code>opus-latest</code>", "Thêm ngày tháng khác vào đuôi cho đến khi chạy được"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Model ID là chuỗi chính xác; tự thêm hậu tố ngày tháng tạo ra ID không tồn tại. <br><strong>Vì sao các lựa chọn khác sai:</strong> Header phiên bản không sửa được ID sai; <code>opus-latest</code> không phải ID hợp lệ; đoán ngày tháng là cách làm không có cơ sở."},
  {"level": 2, "q": "Bạn muốn một script trong <code>packages/shared</code> in ra danh sách model ID mà tài khoản đang dùng được, thay vì chép tay. Cách nào đúng?", "options": ["Đọc file <code>node_modules/@anthropic-ai/sdk/models.txt</code>", "Gọi <code>client.messages.create</code> với <code>model: \"list\"</code>", "Gọi <code>client.models.list()</code> và đọc trường <code>id</code> của từng model", "Tra lịch sử commit của đồng nghiệp"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> SDK có endpoint liệt kê model; kết hợp với trang Models trong tài liệu là nguồn chính xác. <br><strong>Vì sao các lựa chọn khác sai:</strong> SDK không kèm file danh sách model; <code>\"list\"</code> không phải model ID; chép từ commit cũ dễ dùng ID lỗi thời."},
  {"level": 2, "q": "Đoạn log trong NestJS sau đang ghi sai thông tin chi phí. Dòng nào nên thay thế?<pre><code>const r = await this.claude.messages.create(params);\nthis.logger.log(`feature=${feature} size=${JSON.stringify(r).length}`);</code></pre>", "options": ["Ghi <code>r.content.length</code>", "Ghi <code>JSON.stringify(r).length</code>", "Ghi <code>r.usage.input_tokens</code> và <code>r.usage.output_tokens</code> cùng <code>r.model</code>", "Ghi <code>r.stop_reason</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Chi phí thật tính từ <code>usage</code>; cần cả input, output và model để áp đúng đơn giá. <br><strong>Vì sao các lựa chọn khác sai:</strong> Số block hay độ dài JSON không phải số token; <code>stop_reason</code> không chứa thông tin chi phí."},
  {"level": 2, "q": "Worker NestJS gọi Claude đôi khi nhận lỗi giới hạn tốc độ. Cách bắt lỗi nào đúng với SDK TypeScript?<pre><code>try {\n  return await this.claude.messages.create(params);\n} catch (err) {\n  // xử lý ở đây?\n}</code></pre>", "options": ["Kiểm tra <code>err instanceof Anthropic.RateLimitError</code> rồi retry có backoff", "So khớp chuỗi <code>err.message.includes(\"rate\")</code>", "Bọc mọi lỗi và trả về chuỗi rỗng", "Tăng <code>max_tokens</code> để giảm số request"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> SDK có các class lỗi có kiểu (<code>RateLimitError</code>, <code>AuthenticationError</code>, <code>APIError</code>...) nên kiểm tra bằng <code>instanceof</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> So khớp chuỗi dễ vỡ khi thông điệp thay đổi; nuốt lỗi làm mất dấu sự cố; <code>max_tokens</code> không liên quan tới rate limit."},
  {"level": 2, "q": "Sau khi stream xong câu trả lời, bạn cần <code>usage</code> để lưu vào bảng UsageLog. Cách lấy đúng?<pre><code>const stream = client.messages.stream({ model: \"claude-opus-5\", max_tokens: 64000, messages });\nfor await (const event of stream) { /* đẩy text ra client */ }</code></pre>", "options": ["Cộng độ dài các chuỗi text delta", "Gọi lại <code>messages.create</code> với cùng prompt để lấy usage", "Streaming không cung cấp usage", "<code>const msg = await stream.finalMessage();</code> rồi đọc <code>msg.usage</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> <code>finalMessage()</code> trả về Message hoàn chỉnh, kèm <code>usage</code> và <code>stop_reason</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> Độ dài chuỗi không phải số token; gọi lại tốn tiền gấp đôi; streaming vẫn cung cấp usage."},
  {"level": 2, "q": "Trong route handler, cách đơn giản nhất để nhận từng đoạn text khi stream là gì?<pre><code>const stream = client.messages.stream({ model: \"claude-sonnet-5\", max_tokens: 8000, messages });\n// đăng ký nhận text delta ở đây\nconst final = await stream.finalMessage();</code></pre>", "options": ["<code>stream.on(\"token\", ...)</code>", "<code>stream.on(\"text\", (delta) =&gt; ...)</code>", "<code>stream.onMessage(...)</code>", "Polling <code>stream.content</code> mỗi 100 ms"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Sự kiện <code>text</code> của helper stream trả về đúng phần text mới sinh ra. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>token</code> và <code>onMessage</code> không phải API của helper stream; polling không phải cách nhận dữ liệu stream."},
  {"level": 2, "q": "Workload nào phù hợp nhất với Batch API?", "options": ["Lambda chạy lúc 1 giờ sáng phân loại toàn bộ đánh giá trong ngày từ S3, kết quả cần trước 8 giờ sáng", "Chat hỗ trợ khách hàng realtime trên Next.js", "Autocomplete khi người dùng gõ trong form", "Agent review PR cần kết quả trước khi merge trong vài phút"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Batch API xử lý bất đồng bộ, rẻ hơn khoảng 50%, hợp với việc không cần kết quả ngay. <br><strong>Vì sao các lựa chọn khác sai:</strong> Chat realtime, autocomplete và review PR cần trả lời nhanh nên phải dùng request thường."},
  {"level": 2, "q": "Agent chính (Opus) giao cho subagent việc đọc file và tóm tắt nội dung. Model hợp lý cho subagent?", "options": ["Opus effort max", "Haiku hoặc Sonnet", "Bắt buộc cùng model với agent chính", "Không cần model, dùng regex"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Đọc và tóm tắt là việc đơn giản, lặp nhiều; model nhỏ giúp giảm chi phí và độ trễ. <br><strong>Vì sao các lựa chọn khác sai:</strong> Opus effort max lãng phí cho việc nhẹ; không có quy định subagent phải cùng model; regex không tóm tắt được nội dung."},
  {"level": 2, "q": "Team muốn bắt đầu dự án mới bằng Haiku \"cho rẻ\", chưa có bộ eval. Lời khuyên theo bài học?", "options": ["Đồng ý, luôn bắt đầu bằng model rẻ nhất", "Dùng cả ba model rồi chọn ngẫu nhiên", "Chứng minh bài toán làm được bằng model mạnh trước, xây eval, rồi mới thử model rẻ hơn", "Bỏ qua eval, xem phản hồi người dùng sau khi ra mắt"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Nguyên tắc \"mạnh trước – đo – rẻ dần\": nếu bắt đầu bằng model yếu, bạn có thể kết luận sai là bài toán không làm được. <br><strong>Vì sao các lựa chọn khác sai:</strong> Bắt đầu rẻ khi chưa đo dễ đánh giá sai; chọn ngẫu nhiên không có cơ sở; đợi người dùng phản hồi là để lỗi lọt ra production."},
  {"level": 2, "q": "Câu hỏi của người dùng chỉ khoảng 20 token nhưng <code>input_tokens</code> mỗi request là 18.000. Service gửi kèm 40 định nghĩa tool. Giải thích hợp lý nhất?", "options": ["SDK tự thêm dữ liệu quảng cáo", "Output bị tính nhầm vào input", "Tool chỉ tính token khi model gọi tool", "Định nghĩa tool và system prompt đều tính vào token input của mỗi request"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Context window gồm cả định nghĩa tool; 40 tool có schema dài làm input tăng mạnh. <br><strong>Vì sao các lựa chọn khác sai:</strong> SDK không chèn dữ liệu ngoài; input và output được đếm riêng; định nghĩa tool luôn được gửi và tính token dù có dùng hay không."},
  {"level": 2, "q": "Bước nào trong GitHub Actions truyền API key cho job chạy eval một cách an toàn?<pre><code>- name: Run eval\n  run: pnpm --filter eval start\n  # cấu hình key ở đây?</code></pre>", "options": ["<code>run: echo \"key=${{ secrets.ANTHROPIC_API_KEY }}\" &gt;&gt; eval.log</code>", "Ghi key vào <code>.github/workflows/eval.yml</code> dạng plain text", "Dùng <code>env: ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}</code> ở bước chạy script", "Commit file <code>.env</code> chứa key vào repo"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> GitHub Secrets được mask trong log và chỉ nạp vào môi trường khi job chạy. <br><strong>Vì sao các lựa chọn khác sai:</strong> Ghi key ra file log dễ bị upload làm artifact; key trong workflow hay <code>.env</code> commit lên repo đều lộ cho mọi người đọc repo."},
  {"level": 2, "q": "Component Next.js sau gọi Claude từ trình duyệt. Vấn đề nghiêm trọng nhất?<pre><code>\"use client\";\nconst client = new Anthropic({ apiKey: process.env.NEXT_PUBLIC_ANTHROPIC_API_KEY, dangerouslyAllowBrowser: true });</code></pre>", "options": ["Không có vấn đề nếu dùng HTTPS", "Chỉ chậm hơn một chút", "Chỉ cần đổi sang <code>claude-haiku-4-5</code> là an toàn", "Biến <code>NEXT_PUBLIC_</code> được đưa vào bundle phía client, làm lộ API key; phải gọi từ server (route handler hoặc <code>apps/api</code>)"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Mọi biến <code>NEXT_PUBLIC_</code> đều nằm trong JavaScript gửi xuống trình duyệt, ai cũng đọc được. <br><strong>Vì sao các lựa chọn khác sai:</strong> HTTPS mã hoá đường truyền nhưng key vẫn nằm trong bundle; vấn đề là bảo mật chứ không phải tốc độ; đổi model không che được key."},
  {"level": 2, "q": "Request sau trả lỗi 400. Nguyên nhân?<pre><code>await client.messages.create({\n  model: \"claude-opus-5\",\n  max_tokens: 16000,\n  thinking: { type: \"enabled\", budget_tokens: 8000 },\n  messages,\n});</code></pre>", "options": ["<code>max_tokens</code> phải nhỏ hơn 8000", "<code>budget_tokens</code> đã bị bỏ trên Claude Opus 5; dùng <code>thinking: { type: \"adaptive\" }</code> và điều chỉnh bằng <code>effort</code>", "Thiếu tham số <code>system</code>", "Opus 5 không hỗ trợ thinking"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Trên Opus 5, gửi <code>budget_tokens</code> trả 400; mức suy nghĩ được điều chỉnh qua adaptive thinking và <code>output_config.effort</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>max_tokens</code> 16000 hợp lệ; <code>system</code> là tuỳ chọn; Opus 5 có thinking, thậm chí bật mặc định."},
  {"level": 2, "q": "Tính năng tóm tắt ticket dùng Sonnet cho chất lượng tốt nhưng độ trễ và chi phí hơi cao. Bước thử tối ưu đầu tiên hợp lý?", "options": ["Giảm <code>effort</code> (ví dụ xuống <code>low</code> hoặc <code>medium</code>) rồi đo lại bằng eval", "Chuyển ngay sang Haiku không đo", "Tăng <code>max_tokens</code> lên 64.000", "Bỏ system prompt để giảm token"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Bài học gợi ý thử model rẻ hơn hoặc giảm effort, và luôn đo xem chất lượng có giữ được không. <br><strong>Vì sao các lựa chọn khác sai:</strong> Đổi model không đo là rủi ro; tăng <code>max_tokens</code> không giảm độ trễ hay chi phí; bỏ system prompt làm mất chỉ dẫn và giảm chất lượng."},
  {"level": 2, "q": "Bạn muốn Claude trả JSON đúng schema cho endpoint NestJS. Cách phù hợp với model hiện tại?<pre><code>await client.messages.create({\n  model: \"claude-opus-5\",\n  max_tokens: 2048,\n  messages: [\n    { role: \"user\", content: ticketText },\n    { role: \"assistant\", content: \"{\" },\n  ],\n});</code></pre>", "options": ["Prefill lượt assistant bằng <code>{</code> để ép JSON", "Viết HOA \"CHỈ TRẢ JSON\" ở cuối prompt", "Dùng structured output qua <code>output_config: { format: ... }</code> với JSON schema", "Đặt <code>max_tokens</code> thật thấp để model không kịp viết thêm chữ"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> <code>output_config.format</code> ràng buộc output theo schema; prefill không được hỗ trợ trên các model mới. <br><strong>Vì sao các lựa chọn khác sai:</strong> Prefill lượt assistant không còn là cách dùng được; viết HOA không đảm bảo định dạng; <code>max_tokens</code> thấp chỉ làm JSON bị cắt."},
  {"level": 2, "q": "Chi phí sau khi tối ưu là 35 USD/ngày. Ước tính chi phí mỗi tháng (30 ngày)?", "options": ["105 USD", "350 USD", "10.500 USD", "1.050 USD"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> 35 × 30 = 1.050 USD. <br><strong>Vì sao các lựa chọn khác sai:</strong> 105 và 10.500 sai một bậc 10; 350 tương ứng 10 ngày chứ không phải 30 ngày."},
  {"level": 2, "q": "Trong <code>usage</code> của response, trường <code>cache_read_input_tokens</code> cho biết gì?", "options": ["Số token output được lưu cache cho lần sau", "Số token input được đọc từ prompt cache (rẻ hơn nhiều so với input thường)", "Số token bị từ chối vì vượt context window", "Tổng token của cả hội thoại từ trước đến nay"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Trường này đếm phần tiền tố được phục vụ từ cache; chi tiết caching học ở tháng 5. <br><strong>Vì sao các lựa chọn khác sai:</strong> Output không được cache theo nghĩa này; token vượt window gây lỗi chứ không được đếm; API không cộng dồn qua các request."},
  {"level": 2, "q": "Phòng marketing muốn tóm tắt tài liệu trên Google Drive bằng giao diện chat; đội dev muốn thêm tính năng tóm tắt vào sản phẩm Next.js. Chọn bề mặt nào?", "options": ["Marketing dùng claude.ai (có Connectors); đội dev dùng Claude API qua backend", "Cả hai cùng dùng Claude Code", "Cả hai cùng gọi API trực tiếp từ trình duyệt", "Marketing dùng Batch API; đội dev dùng claude.ai"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> claude.ai dành cho người dùng cuối với Projects/Connectors; tính năng sản phẩm phải tích hợp qua API. <br><strong>Vì sao các lựa chọn khác sai:</strong> Claude Code là agent lập trình; gọi API từ trình duyệt lộ key; Batch API không phải giao diện chat và claude.ai không nhúng vào sản phẩm của bạn."},
  {"level": 2, "q": "Model ID đang bị chép ở 12 chỗ trong <code>apps/api</code> và <code>apps/web</code>. Cách tổ chức tốt nhất trong monorepo?<pre><code>// apps/api/src/tickets/tickets.service.ts\nmodel: \"claude-sonnet-5\",\n// apps/web/app/api/chat/route.ts\nmodel: \"claude-sonnet-5\",\n// apps/api/src/reviews/reviews.service.ts\nmodel: \"claude-haiku-4-5\",</code></pre>", "options": ["Định nghĩa hằng số/cấu hình trong <code>packages/shared</code>, cho phép ghi đè bằng biến môi trường", "Giữ nguyên, mỗi app tự quản lý", "Hardcode vào <code>turbo.json</code>", "Lưu model ID trong cookie người dùng"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Một nguồn cấu hình dùng chung giúp đổi model một chỗ và dễ chạy eval trước khi đổi. <br><strong>Vì sao các lựa chọn khác sai:</strong> Chép rải rác dễ lệch phiên bản; <code>turbo.json</code> là cấu hình pipeline build; cookie người dùng không phải nơi cấu hình backend."},
  {"level": 2, "q": "Service NestJS sau thỉnh thoảng ném <code>SyntaxError: Unexpected end of JSON input</code>. Cách sửa hợp lý nhất?<pre><code>const r = await this.claude.messages.create({ model, max_tokens: 512, messages });\nconst text = r.content.find((b) =&gt; b.type === \"text\")?.text ?? \"\";\nreturn JSON.parse(text);</code></pre>", "options": ["Bọc <code>JSON.parse</code> trong try/catch và trả <code>{}</code>", "Kiểm tra <code>stop_reason</code> trước khi parse; nếu là <code>\"max_tokens\"</code> thì tăng giới hạn hoặc xử lý riêng", "Giảm <code>max_tokens</code> để JSON ngắn hơn", "Đổi model mỗi lần lỗi"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> JSON bị cắt dở vì chạm <code>max_tokens</code>; phát hiện qua <code>stop_reason</code> và xử lý đúng nguyên nhân. <br><strong>Vì sao các lựa chọn khác sai:</strong> Trả <code>{}</code> che lỗi và mất dữ liệu; giảm giới hạn làm cắt nhiều hơn; đổi model không giải quyết giới hạn output."},
  {"level": 2, "q": "Đoạn code sau tự nhân <code>max_tokens</code> lên 4 lần mỗi khi bị cắt. Nhận xét đúng nhất?<pre><code>while (true) {\n  const r = await client.messages.create({ model, max_tokens: maxTokens, messages });\n  if (r.stop_reason !== \"max_tokens\" || maxTokens &gt;= 16000) return r;\n  maxTokens = Math.min(maxTokens * 4, 16000);\n}</code></pre>", "options": ["Đây là cách tối ưu nhất", "Nên nhân 10 để ít lần thử hơn", "Nên giảm <code>max_tokens</code> sau mỗi lần thử", "Mỗi lần thử lại đều tốn tiền; nên đặt <code>max_tokens</code> đủ lớn ngay từ đầu cho loại việc đó"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Bài học nêu rõ đặt giới hạn đủ lớn ngay từ đầu vì bạn chỉ trả tiền cho token thực sinh ra. <br><strong>Vì sao các lựa chọn khác sai:</strong> Thử lại lặp lại toàn bộ input và phần output đã sinh; nhân 10 vẫn là thử lại; giảm giới hạn làm cắt nhiều hơn."},
  {"level": 2, "q": "Vì sao khi input đã gần chạm trần context window, câu trả lời vẫn có thể bị thiếu chỗ?", "options": ["Vì <code>max_tokens</code> bị tự động đặt về 0", "Vì model chỉ đọc 50% đầu của input", "Context window tính cả output, nên input sát trần sẽ còn rất ít chỗ cho output", "Vì system prompt không tính vào context"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tổng input và output cùng nằm trong một context window, nên cần chừa chỗ cho phần trả lời. <br><strong>Vì sao các lựa chọn khác sai:</strong> API không tự đổi <code>max_tokens</code> về 0; model đọc toàn bộ context; system prompt có tính vào context."},
  {"level": 2, "q": "Job phân loại tốn 90 USD/ngày bằng request thường. Nếu chuyển toàn bộ sang Batch API (giảm khoảng 50%) thì mỗi tháng 30 ngày tốn khoảng bao nhiêu?", "options": ["Khoảng 2.700 USD", "Khoảng 450 USD", "Khoảng 1.350 USD", "Khoảng 135 USD"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> 90 × 50% = 45 USD/ngày; × 30 = 1.350 USD/tháng. <br><strong>Vì sao các lựa chọn khác sai:</strong> 2.700 USD là chưa giảm; 450 và 135 là tính sai số ngày hoặc sai bậc 10."},
  {"level": 2, "q": "NestJS chạy tốt ở máy dev nhưng sau khi deploy lên ECS Fargate thì mọi request tới Claude trả <code>AuthenticationError</code>. Nguyên nhân khả dĩ nhất?<pre><code>{\n  \"containerDefinitions\": [{\n    \"name\": \"api\",\n    \"image\": \"123456789012.dkr.ecr.ap-southeast-1.amazonaws.com/api:latest\",\n    \"environment\": [{ \"name\": \"NODE_ENV\", \"value\": \"production\" }]\n  }]\n}</code></pre>", "options": ["Fargate không hỗ trợ gọi HTTPS ra ngoài", "Model ID ở production phải khác ở dev", "Cần bật streaming trên production", "Task definition chưa nạp secret <code>ANTHROPIC_API_KEY</code> (ví dụ từ Secrets Manager) vào container"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Lỗi xác thực khi môi trường mới thường do thiếu hoặc sai biến chứa key. <br><strong>Vì sao các lựa chọn khác sai:</strong> Fargate gọi HTTPS ra ngoài được nếu có đường mạng; model ID không phụ thuộc môi trường; streaming không liên quan xác thực."},
  {"level": 3, "q": "Monorepo e-commerce: <code>apps/api</code> (NestJS) dùng Opus cho cả phân loại 50.000 đánh giá/ngày lẫn soạn trả lời khiếu nại phức tạp. Hoá đơn tháng vượt dự tính nhiều lần. Kế hoạch tối ưu đúng nhất?", "options": ["Chuyển toàn bộ sang Haiku ngay để giảm chi phí", "Log <code>usage</code> theo từng tính năng, eval Haiku trên tập có nhãn cho phân loại và chuyển nếu đạt ngưỡng, giữ Opus cho khiếu nại, chạy phân loại ban đêm bằng Batch API", "Giảm <code>max_tokens</code> của mọi request xuống 200", "Bật prompt caching cho tất cả và giữ Opus cho mọi việc"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chọn model theo từng việc dựa trên số đo: phân loại khối lượng lớn sang model nhỏ và Batch, việc khó giữ model mạnh. <br><strong>Vì sao các lựa chọn khác sai:</strong> Đổi hết sang Haiku không đo có thể làm hỏng chất lượng khiếu nại; <code>max_tokens</code> thấp chỉ cắt output; caching giúp phần tiền tố lặp lại nhưng không giải quyết việc dùng model quá mạnh cho việc đơn giản."},
  {"level": 3, "q": "Chatbot tư vấn thẻ trên Next.js + NestJS \"quên\" thông tin khách, và sau khi sửa thì chi phí mỗi phiên tăng dần. Yêu cầu: nhớ đúng, chi phí kiểm soát được, chạy trên nhiều task ECS. Thiết kế đúng nhất?", "options": ["Lưu lịch sử trong PostgreSQL qua Prisma theo conversationId, gửi lại mỗi lượt, giới hạn/tóm tắt phần cũ và theo dõi <code>input_tokens</code>", "Lưu lịch sử trong RAM của từng task ECS và bật sticky session", "Chỉ gửi câu hỏi mới nhất và nhờ model \"hãy nhớ\"", "Nhét toàn bộ lịch sử vào system prompt để được cache"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> API stateless nên ứng dụng tự lưu lịch sử ở nơi mọi task đọc được; giới hạn độ dài kiểm soát input tăng dần. <br><strong>Vì sao các lựa chọn khác sai:</strong> RAM mất khi task restart hoặc scale; model không nhớ thứ không được gửi; lịch sử thay đổi mỗi lượt trong system prompt làm lẫn vai trò và phá cache."},
  {"level": 3, "q": "Mỗi đêm cần phân loại 1 triệu đánh giá nằm trong S3, kết quả cần có trước 8 giờ sáng, ưu tiên chi phí thấp nhất. Kiến trúc hợp lý?", "options": ["ECS service gọi Opus tuần tự từng đánh giá", "Next.js route handler stream từng đánh giá", "Lambda theo lịch gửi Batch API với model nhỏ đã qua eval, một Lambda khác kiểm tra và ghi kết quả vào RDS khi batch xong", "Gửi cả 1 triệu đánh giá trong một request duy nhất"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Việc không cần realtime, khối lượng lớn: Batch API (giảm ~50%) cộng model nhỏ được kiểm chứng là rẻ nhất. <br><strong>Vì sao các lựa chọn khác sai:</strong> Opus tuần tự vừa đắt vừa chậm; streaming phục vụ người dùng đang chờ, không phải job đêm; một request không thể chứa cả triệu đánh giá vì vượt context window."},
  {"level": 3, "q": "NestJS chạy trên ECS Fargate cần API key Claude. Yêu cầu: không có key trong image, repo hay log; xoay vòng được. Phương án đúng?", "options": ["Ghi key vào Dockerfile bằng <code>ENV</code>", "Truyền key qua build arg trong GitHub Actions rồi bake vào image", "Lưu key trong bảng Postgres và đọc bằng Prisma", "Lưu key trong AWS Secrets Manager, tham chiếu trong trường <code>secrets</code> của task definition, cấp quyền đọc cho task execution role"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Secrets Manager + tham chiếu trong task definition nạp key lúc chạy, không dính vào image, và xoay vòng tập trung. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>ENV</code> và build arg đều để key nằm trong layer image; lưu key trong DB ứng dụng làm tăng bề mặt lộ và không có quản lý xoay vòng chuẩn."},
  {"level": 3, "q": "Công ty yêu cầu toàn bộ lưu lượng AI nằm trong tài khoản AWS, xác thực bằng IAM role của ECS task, thanh toán qua AWS. Phương án phù hợp?", "options": ["Gọi Claude API trực tiếp với key lưu trong IAM", "Gọi Claude qua Amazon Bedrock bằng <code>AnthropicBedrockMantle</code> với model ID <code>anthropic.claude-opus-5</code>, và kiểm tra tính năng nào đã có trên Bedrock", "Dùng claude.ai Team cho backend", "Tự host model Claude trên EC2"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Bedrock đáp ứng yêu cầu IAM và billing AWS; model ID có tiền tố <code>anthropic.</code>; tính năng giữa các nền tảng có thể khác nhau nên cần kiểm tra tài liệu. <br><strong>Vì sao các lựa chọn khác sai:</strong> IAM không lưu API key của Anthropic; claude.ai là giao diện người dùng, không phải backend API; model Claude không thể tự host."},
  {"level": 3, "q": "Service NestJS chuyển sang Bedrock nhưng mọi request lỗi model không hợp lệ. IAM role đã đúng quyền. Sửa gì?<pre><code>import { AnthropicBedrockMantle } from \"@anthropic-ai/bedrock-sdk\";\n\nconst client = new AnthropicBedrockMantle({ awsRegion: \"ap-southeast-1\" });\nconst r = await client.messages.create({\n  model: \"claude-opus-5\",\n  max_tokens: 4096,\n  messages: [{ role: \"user\", content: prompt }],\n});</code></pre>", "options": ["Đổi model ID thành <code>anthropic.claude-opus-5</code> theo quy ước của Bedrock", "Thêm <code>apiKey</code> của Claude Console vào client Bedrock", "Đổi <code>awsRegion</code> sang <code>us-east-1</code> là đủ", "Chuyển về <code>@anthropic-ai/sdk</code> và giữ nguyên ID"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Trên Bedrock, model ID có tiền tố <code>anthropic.</code>; ID dạng Claude API trực tiếp không được nhận. <br><strong>Vì sao các lựa chọn khác sai:</strong> Client Bedrock xác thực bằng AWS credential, không dùng key Console; đổi region không sửa ID sai; quay lại SDK gốc là bỏ yêu cầu chạy qua AWS."},
  {"level": 3, "q": "Tính năng chat trên Next.js có SLO: người dùng thấy chữ đầu tiên dưới 3 giây ở p95, chất lượng yêu cầu mức trung bình, ngân sách hạn chế. Cấu hình nào nên thử trước?", "options": ["Opus với effort max để chắc chất lượng", "Sonnet (hoặc Haiku nếu eval đạt) với streaming, đo thời gian tới token đầu tiên và chất lượng trên bộ test", "Batch API để giảm chi phí", "Tắt streaming và tăng <code>max_tokens</code> để trả lời một lần cho gọn"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Model cân bằng kèm streaming đáp ứng độ trễ cảm nhận và chi phí; quyết định cuối dựa trên số đo. <br><strong>Vì sao các lựa chọn khác sai:</strong> Opus effort max tăng độ trễ và chi phí vượt nhu cầu; Batch không trả ngay; tắt streaming làm người dùng chờ tới khi xong toàn bộ."},
  {"level": 3, "q": "Chi phí tháng tăng 40%. Một kỹ sư đề xuất hạ <code>max_tokens</code> của mọi endpoint từ 4.000 xuống 500. Phân tích nào đúng?", "options": ["Hiệu quả vì phí tính theo <code>max_tokens</code>", "Hiệu quả vì giảm luôn token input", "Hiệu quả nếu kết hợp đổi toàn bộ sang Opus", "Không hiệu quả: endpoint trả lời ngắn không đổi chi phí, endpoint dài bị cắt; nên xem <code>usage</code> theo tính năng rồi cắt input thừa, định tuyến model và caching"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Phí output tính theo token thực sinh; phải tìm nơi tiêu tốn thật qua số liệu <code>usage</code>. <br><strong>Vì sao các lựa chọn khác sai:</strong> Phí không dựa trên giới hạn đặt ra; <code>max_tokens</code> không ảnh hưởng input; đổi sang Opus còn tăng chi phí."},
  {"level": 3, "q": "CloudWatch Logs Insights cho endpoint <code>/summaries</code> trả kết quả sau, người dùng phàn nàn bản tóm tắt bị cụt. Xử lý nào đúng?<pre><code>stats count(*) by stop_reason\n| stop_reason   | count |\n| end_turn      |  1180 |\n| max_tokens    |   942 |</code></pre>", "options": ["Tăng <code>max_tokens</code> cho endpoint này (dùng streaming nếu dài) và đặt alarm trên tỉ lệ <code>stop_reason = max_tokens</code>", "Đổi sang model lớn hơn vì model hiện tại \"hết hơi\"", "Bật prompt caching để model viết dài hơn", "Giảm độ dài tài liệu đầu vào"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Tỉ lệ lớn <code>max_tokens</code> cho thấy giới hạn output đặt thấp; sửa đúng chỗ và giám sát để phát hiện tái diễn. <br><strong>Vì sao các lựa chọn khác sai:</strong> Đổi model không đổi giới hạn bạn đặt; caching chỉ liên quan chi phí input; giảm tài liệu không nâng giới hạn output – đây đều là bẫy đề thi."},
  {"level": 3, "q": "SaaS pháp lý cần phân tích hợp đồng có thể dài hơn context window, rủi ro cao nếu bỏ sót. Luồng xử lý hợp lý nhất trong NestJS?", "options": ["Gửi thẳng và để API tự cắt phần thừa", "Dùng Haiku vì tài liệu dài thì cần model nhanh", "Dùng <code>countTokens</code> trước; nếu vượt ngưỡng thì chia theo điều khoản, phân tích từng phần bằng Opus rồi tổng hợp; nếu vừa thì gửi một lần", "Chỉ gửi 20% đầu hợp đồng cho tiết kiệm"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Đo trước để chọn đường xử lý; tài liệu rủi ro cao cần model mạnh và không được bỏ nội dung. <br><strong>Vì sao các lựa chọn khác sai:</strong> Vượt context window trả lỗi 400 chứ không tự cắt; model nhanh không phù hợp khi sai là tốn kém; bỏ 80% nội dung vi phạm yêu cầu không bỏ sót."},
  {"level": 3, "q": "Team muốn đổi tính năng phân loại ticket từ Opus sang Haiku để tiết kiệm, nhưng sợ giảm chất lượng mà không ai phát hiện. Quy trình nào tốt nhất?", "options": ["Tạo tập mẫu có nhãn, thêm job GitHub Actions chạy eval cả hai model và chặn merge nếu độ chính xác dưới ngưỡng", "Đổi trực tiếp trên production rồi theo dõi khiếu nại", "Hỏi Claude \"Haiku có đủ tốt không?\"", "Chạy thử 3 ví dụ bằng tay rồi quyết định"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Eval có nhãn chạy tự động trong CI biến quyết định đổi model thành một phép đo lặp lại được. <br><strong>Vì sao các lựa chọn khác sai:</strong> Đợi khiếu nại là để lỗi lọt ra người dùng; hỏi model không thay cho đo lường; 3 ví dụ là quá ít và output có tính ngẫu nhiên."},
  {"level": 3, "q": "Endpoint NestJS sau nhận nguyên lịch sử hội thoại từ trình duyệt rồi chuyển thẳng cho Claude. Rủi ro chính và thiết kế tốt hơn?<pre><code>@Post(\"chat\")\nchat(@Body() body: { messages: Anthropic.MessageParam[] }) {\n  return this.claude.messages.create({ model, max_tokens: 2048, system: SYSTEM, messages: body.messages });\n}</code></pre>", "options": ["Không có rủi ro vì dùng HTTPS", "Client có thể giả mạo lượt <code>assistant</code> hoặc chèn lịch sử tuỳ ý; nên lưu lịch sử phía server theo conversationId và chỉ nhận câu hỏi mới", "Chỉ rủi ro về hiệu năng, thêm gzip là đủ", "Chỉ cần giới hạn độ dài body 1 MB"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Tin tưởng lịch sử do client gửi cho phép người dùng dựng hội thoại giả để lách quy tắc; server phải là nguồn sự thật. <br><strong>Vì sao các lựa chọn khác sai:</strong> HTTPS không chống người dùng tự sửa dữ liệu; gzip và giới hạn kích thước không ngăn nội dung giả mạo."},
  {"level": 3, "q": "Team ước tính chi phí bằng cách đếm token trên bản dịch tiếng Anh của dữ liệu mẫu. Thực tế dữ liệu là tiếng Việt và hoá đơn cao hơn dự toán. Cách ước tính đúng cho lần sau?", "options": ["Nhân số từ tiếng Anh với 1,3", "Dùng giá output cho cả input để dư ra", "Chạy <code>countTokens</code> trên mẫu dữ liệu tiếng Việt thật (gồm cả system prompt và tool) rồi nhân theo lưu lượng", "Ước tính theo số ký tự chia 4"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tiếng Việt thường tốn nhiều token hơn; chỉ đếm trên dữ liệu thật với tokenizer của model mới chính xác. <br><strong>Vì sao các lựa chọn khác sai:</strong> Hệ số theo số từ hay số ký tự chỉ là quy tắc thô, lệch với tiếng Việt; dùng giá output cho input không phản ánh cơ cấu chi phí thật."},
  {"level": 3, "q": "Agent tự động sửa bug gồm: một agent điều phối lập kế hoạch và sửa code, nhiều subagent chỉ đọc file và tóm tắt. Cần cân bằng chất lượng và chi phí. Phân bổ model hợp lý?", "options": ["Tất cả dùng Haiku", "Tất cả dùng Opus effort max", "Agent điều phối dùng Haiku, subagent dùng Opus", "Agent điều phối dùng Opus; subagent đọc/tóm tắt dùng Haiku hoặc Sonnet, xác nhận bằng eval"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Việc suy luận nhiều bước cần model mạnh; việc đọc và tóm tắt lặp nhiều nên dùng model nhỏ. <br><strong>Vì sao các lựa chọn khác sai:</strong> Haiku cho mọi việc có thể làm hỏng phần lập kế hoạch; Opus effort max cho mọi việc lãng phí; đảo ngược vai trò đặt model mạnh vào việc nhẹ."},
  {"level": 3, "q": "Route handler Next.js sau dùng streaming nhưng người dùng vẫn phải chờ tới khi toàn bộ câu trả lời xong mới thấy chữ. Nguyên nhân?<pre><code>export async function POST(req: Request) {\n  const { messages } = await req.json();\n  const stream = client.messages.stream({ model: \"claude-sonnet-5\", max_tokens: 8000, messages });\n  const msg = await stream.finalMessage();\n  const text = msg.content.map((b) =&gt; (b.type === \"text\" ? b.text : \"\")).join(\"\");\n  return new Response(text);\n}</code></pre>", "options": ["Streaming chỉ chạy trên Python SDK", "Cần tăng <code>max_tokens</code>", "Code <code>await stream.finalMessage()</code> trước khi trả <code>Response</code>, nên không đẩy từng đoạn text về client", "Next.js App Router không hỗ trợ trả stream"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Chờ <code>finalMessage()</code> là chờ hết output; phải trả <code>ReadableStream</code> và ghi từng delta, rồi lưu usage khi stream kết thúc. <br><strong>Vì sao các lựa chọn khác sai:</strong> TypeScript SDK có streaming; <code>max_tokens</code> không ảnh hưởng thời điểm hiển thị; route handler trả được <code>ReadableStream</code>."},
  {"level": 3, "q": "Một tính năng có trung bình 3.000 token input và 1.500 token output, giá 5 USD/1M input và 25 USD/1M output. Thay đổi nào giảm chi phí mỗi request nhiều nhất?", "options": ["Cắt 20% system prompt", "Yêu cầu định dạng ngắn gọn hơn để giảm 40% output", "Hạ <code>max_tokens</code> từ 4.000 xuống 3.000", "Đổi region AWS"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Input tốn 0,015 USD, output tốn 0,0375 USD; giảm 40% output tiết kiệm 0,015 USD, cắt 20% input chỉ tiết kiệm khoảng 0,003 USD. <br><strong>Vì sao các lựa chọn khác sai:</strong> Cắt input có tác dụng nhỏ vì output chiếm phần lớn chi phí; hạ <code>max_tokens</code> trên mức output thật không đổi chi phí; region không đổi đơn giá theo bài học."},
  {"level": 3, "q": "Anthropic ra model mới. Model ID đang được chép cứng rải rác ở <code>apps/api</code> và <code>apps/web</code>. Chiến lược nâng cấp an toàn nhất?", "options": ["Gom model ID vào cấu hình trong <code>packages/shared</code> (ghi đè được bằng biến môi trường), chạy eval trong CI với model mới, rồi đổi cấu hình theo từng tính năng", "Find-and-replace toàn repo sang ID mới rồi deploy", "Tự đoán ID mới bằng cách thêm ngày phát hành", "Giữ model cũ mãi mãi để tránh rủi ro"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Một nguồn cấu hình cùng eval tự động cho phép đổi có kiểm soát và rollback nhanh. <br><strong>Vì sao các lựa chọn khác sai:</strong> Thay hàng loạt không đo dễ làm hỏng tính năng; đoán ID là bẫy; model cũ có thể bị ngừng hỗ trợ."},
  {"level": 3, "q": "Giờ cao điểm, NestJS gặp nhiều <code>RateLimitError</code> khi vừa phục vụ chat realtime vừa chạy tóm tắt ticket hàng loạt. Thiết kế nào hợp lý?<pre><code>[ChatService] RateLimitError: 429 rate_limit_error\n[TicketSummaryJob] RateLimitError: 429 rate_limit_error\n[TicketSummaryJob] processing 4.800 tickets concurrently...</code></pre>", "options": ["Bắt lỗi và trả chuỗi rỗng cho người dùng", "Tăng <code>max_tokens</code> để mỗi request làm được nhiều hơn", "Mở thêm task ECS để gọi nhiều hơn cùng lúc", "Retry có backoff cho chat; chuyển tóm tắt hàng loạt sang SQS + Lambda xử lý với tốc độ giới hạn (hoặc Batch API nếu không gấp)"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Tách lưu lượng không gấp ra hàng đợi giảm áp lực lên hạn mức, còn chat được ưu tiên và retry hợp lý. <br><strong>Vì sao các lựa chọn khác sai:</strong> Trả chuỗi rỗng che lỗi; <code>max_tokens</code> không liên quan hạn mức request; thêm task chỉ gửi nhiều request hơn và làm rate limit nặng hơn."},
  {"level": 3, "q": "Câu hỏi kiểu đề thi: output của tính năng tóm tắt hợp đồng bị cắt giữa chừng; log có <code>stop_reason: \"max_tokens\"</code>. Đồng nghiệp đề xuất bốn cách. Cách nào đúng?", "options": ["Bật prompt caching để model \"nhớ\" phần còn lại", "Tăng <code>max_tokens</code> và dùng streaming cho output dài", "Đổi sang model mạnh hơn", "Rút ngắn system prompt để dồn chỗ cho output"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Giới hạn output do bạn đặt là nguyên nhân trực tiếp; streaming tránh timeout khi output dài. <br><strong>Vì sao các lựa chọn khác sai:</strong> Caching chỉ giảm chi phí input; model mạnh hơn vẫn bị cùng giới hạn; system prompt ngắn đi không nâng giới hạn output."},
  {"level": 3, "q": "<code>apps/api</code> chạy 6 task ECS sau ALB, không bật sticky session. Lịch sử chat lưu ở RDS. Nhận định nào đúng về việc gọi Claude?", "options": ["Bắt buộc sticky session vì Claude nhớ hội thoại theo kết nối", "Phải dùng một task duy nhất để giữ ngữ cảnh", "Phải gửi session ID của Claude trong header", "Task nào cũng phục vụ được lượt tiếp theo, vì Claude API stateless và lịch sử được đọc từ RDS rồi gửi lại mỗi request"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Không có trạng thái phía Claude; khi lịch sử nằm ở DB dùng chung, các task hoàn toàn có thể thay thế nhau. <br><strong>Vì sao các lựa chọn khác sai:</strong> Claude không nhớ theo kết nối; giới hạn một task làm mất khả năng mở rộng; Claude API không có session ID hội thoại."},
  {"level": 3, "q": "Trợ lý nội bộ gửi 60 định nghĩa tool trong mọi request, dù mỗi màn hình chỉ cần khoảng 5 tool. Chi phí và độ trễ đều cao. Hướng cải thiện hợp lý?", "options": ["Chỉ gửi nhóm tool liên quan tới ngữ cảnh/route hiện tại, và đo lại <code>input_tokens</code>", "Rút gọn tên tool thành 1 ký tự", "Chuyển định nghĩa tool vào system prompt dạng văn xuôi", "Tăng <code>max_tokens</code> để model chọn tool nhanh hơn"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Định nghĩa tool tính vào input mỗi request; bớt tool không cần thiết giảm cả chi phí lẫn độ trễ. <br><strong>Vì sao các lựa chọn khác sai:</strong> Tên 1 ký tự làm model khó chọn đúng mà tiết kiệm không đáng kể; mô tả tool trong văn xuôi vẫn tốn token và mất cấu trúc; <code>max_tokens</code> không ảnh hưởng input."},
  {"level": 3, "q": "SaaS nhiều tenant muốn giới hạn chi tiêu Claude theo từng tenant mỗi tháng. Thiết kế nào đúng?<pre><code>model Tenant {\n  id             String     @id\n  monthlyBudget  Decimal    @db.Decimal(10, 2)\n  usage          UsageLog[]\n}</code></pre>", "options": ["Đặt <code>max_tokens</code> khác nhau cho từng tenant", "Dựa vào hoá đơn cuối tháng của Anthropic để tính", "Ghi <code>usage</code> (input/output, model, tenantId) vào Postgres sau mỗi request, tính chi phí theo đơn giá, và chặn/cảnh báo khi tenant chạm hạn mức", "Đếm số request của tenant là đủ"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Chi phí thật đến từ <code>usage</code>; lưu theo tenant cho phép kiểm soát gần thời gian thực. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>max_tokens</code> không phản ánh chi tiêu thật; hoá đơn cuối tháng không chia theo tenant và quá muộn; số request bỏ qua độ dài khác nhau của từng request."},
  {"level": 3, "q": "Job review code chạy trong GitHub Actions dùng cấu hình sau và trả lỗi 400. Mục tiêu là giảm thời gian chạy. Cách sửa đúng?<pre><code>await client.messages.create({\n  model: \"claude-opus-5\",\n  max_tokens: 16000,\n  thinking: { type: \"disabled\" },\n  output_config: { effort: \"max\" },\n  messages,\n});</code></pre>", "options": ["Thêm <code>budget_tokens: 0</code> để tắt hẳn", "Không tắt thinking khi effort ở mức <code>xhigh</code>/<code>max</code>; hãy hạ effort (ví dụ <code>medium</code>) và giữ adaptive thinking, rồi đo chất lượng", "Đổi <code>max_tokens</code> thành 1.000", "Bỏ <code>model</code> để API tự chọn"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Trên Opus 5, <code>thinking: { type: \"disabled\" }</code> chỉ được nhận ở effort <code>high</code> trở xuống; ghép với <code>max</code> trả 400. <br><strong>Vì sao các lựa chọn khác sai:</strong> <code>budget_tokens</code> đã bị bỏ trên Opus 5; <code>max_tokens</code> không phải nguyên nhân lỗi; <code>model</code> là tham số bắt buộc."},
  {"level": 3, "q": "Trợ lý phân tích dữ liệu trên Next.js dùng Opus mất khoảng 25 giây mới hiện câu trả lời; nhiều người thoát trang. Yêu cầu giữ chất lượng Opus. Giải pháp phù hợp nhất?", "options": ["Chuyển sang Batch API", "Đổi sang Haiku không cần đo", "Bật streaming để hiển thị chữ ngay khi model bắt đầu sinh, và cân nhắc giảm effort nếu eval cho phép", "Giảm <code>max_tokens</code> xuống 300"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Streaming giảm độ trễ cảm nhận mà không đổi model; effort là nút điều chỉnh thêm có kiểm chứng. <br><strong>Vì sao các lựa chọn khác sai:</strong> Batch không trả kết quả ngay; đổi model vi phạm yêu cầu chất lượng; cắt <code>max_tokens</code> làm câu trả lời bị cụt."},
  {"level": 3, "q": "Hàm tính chi phí trong <code>packages/shared</code> sau khiến dashboard báo chi phí cao gấp 1.000 lần thực tế. Lỗi ở đâu?<pre><code>export function costUsd(u: { input_tokens: number; output_tokens: number }, p: { in: number; out: number }) {\n  return (u.input_tokens * p.in + u.output_tokens * p.out) / 1_000;\n}</code></pre>", "options": ["Không được cộng chi phí input và output", "Phải nhân thêm số lượt hội thoại", "Phải dùng <code>max_tokens</code> thay cho <code>output_tokens</code>", "Chia cho 1.000 thay vì 1.000.000, trong khi đơn giá tính theo USD / 1 triệu token"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Đơn giá niêm yết theo triệu token nên mẫu số phải là 1.000.000. <br><strong>Vì sao các lựa chọn khác sai:</strong> Chi phí đúng là tổng input và output; <code>usage</code> đã là số của request đó; dùng <code>max_tokens</code> sẽ tính theo giới hạn chứ không theo thực tế."},
  {"level": 3, "q": "Hệ thống ticket có hai luồng: thống kê chủ đề toàn bộ ticket mỗi đêm, và gắn nhãn khẩn cấp cho ticket mới trong vòng 1 phút. Cách gọi API phù hợp?", "options": ["Thống kê đêm dùng Batch API; gắn nhãn khẩn cấp dùng request thường (ví dụ Lambda đọc SQS) với model nhỏ đã qua eval", "Cả hai dùng Batch API cho rẻ", "Cả hai dùng Opus với streaming", "Cả hai chạy trong một request duy nhất mỗi giờ"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Chọn cách gọi theo yêu cầu độ trễ của từng luồng: việc không gấp dùng Batch, việc cần nhanh gọi đồng bộ. <br><strong>Vì sao các lựa chọn khác sai:</strong> Batch không đảm bảo 1 phút; Opus streaming cho job nền là lãng phí và streaming không cần khi không có người chờ; gom mỗi giờ vi phạm yêu cầu 1 phút."},
  {"level": 3, "q": "Một dev lỡ push API key Claude lên repo GitHub public. Chuỗi hành động đúng?", "options": ["Thu hồi và tạo key mới trên Claude Console ngay, cập nhật Secrets Manager/GitHub Secrets, bật secret scanning; xoá khỏi lịch sử git chỉ là bước phụ", "Chỉ cần force-push xoá commit", "Đổi repo sang private là đủ", "Giữ key, chỉ theo dõi hoá đơn"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Key đã lộ công khai phải coi là đã bị lấy; thu hồi là bước bắt buộc, sau đó chuẩn hoá cách lưu key. <br><strong>Vì sao các lựa chọn khác sai:</strong> Force-push không xoá được bản sao đã bị thu thập; chuyển private không vô hiệu key; theo dõi hoá đơn là chấp nhận rủi ro bị lạm dụng."},
  {"level": 3, "q": "Lãnh đạo muốn biết tính năng nào của sản phẩm tốn nhiều chi phí Claude nhất theo ngày, xem trên CloudWatch. Cách triển khai hợp lý?", "options": ["Chỉ đếm số lỗi 4xx/5xx", "Sau mỗi request, phát metric (hoặc log có cấu trúc) với <code>input_tokens</code>, <code>output_tokens</code>, dimension <code>feature</code> và <code>model</code>, rồi tính chi phí theo đơn giá trên dashboard", "Đo CPU của task ECS", "Đo số dòng code gọi Claude trong repo"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chi phí tính từ token theo model; gắn nhãn theo tính năng mới phân bổ được. <br><strong>Vì sao các lựa chọn khác sai:</strong> Số lỗi, CPU hay số dòng code không phản ánh token tiêu thụ."},
  {"level": 3, "q": "Phiên chat hỗ trợ kỹ thuật dài tới lượt 80 thì bắt đầu trả lỗi 400. Yêu cầu: người dùng vẫn tiếp tục được, chi phí không tăng vô hạn. Giải pháp đúng?", "options": ["Tăng <code>max_tokens</code>", "Đổi sang Haiku", "Bật prompt caching", "Giữ N lượt gần nhất cộng bản tóm tắt phần cũ (lưu ở DB), hoặc dùng compaction phía server nếu model hỗ trợ"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Lỗi do lịch sử vượt context window; phải giảm kích thước lịch sử gửi lên. <br><strong>Vì sao các lựa chọn khác sai:</strong> Tăng <code>max_tokens</code> còn làm thiếu chỗ hơn; đổi model không giải quyết việc lịch sử tăng mãi; caching giảm chi phí nhưng không giảm số token trong context."},
  {"level": 3, "q": "Thiết kế hệ thống hỗ trợ khách hàng trên stack NestJS + Next.js + AWS: (1) phân loại ticket khi tạo, (2) soạn nháp trả lời cho nhân viên xem ngay trên web, (3) báo cáo xu hướng hằng tuần. Phương án tổng thể tốt nhất?", "options": ["Opus cho cả ba, gọi đồng bộ từ Next.js client", "Haiku cho cả ba để tiết kiệm tối đa", "(1) Haiku qua SQS + Lambda, (2) Sonnet/Opus với streaming từ NestJS, (3) Batch API; key trong Secrets Manager và log <code>usage</code> theo tính năng", "Batch API cho cả ba"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Mỗi việc chọn model và cách gọi theo độ khó, độ trễ và khối lượng; bảo mật key và đo chi phí là nền tảng. <br><strong>Vì sao các lựa chọn khác sai:</strong> Opus cho mọi việc gọi từ client vừa đắt vừa lộ key; Haiku cho soạn trả lời có thể không đủ chất lượng; Batch không đáp ứng nhu cầu xem ngay."},
];
